<script lang="ts">
 import { enhance, type SubmitFunction } from '$app/forms';
 import '../../../../app.css';import '#lib/v2/styles/v2.css';import imgLogo from '#lib/assets/images/logo.png';import {ArrowLeft,MailCheck,ShieldCheck} from '@lucide/svelte';import type{PageProps}from'./$types';let{data,form}:PageProps=$props();let code=$state('');let busy=$state(false);let resending=$state(false);
 const handleVerify: SubmitFunction = () => { busy = true; return async ({ update }) => { await update(); busy = false; }; };
 const handleResend: SubmitFunction = () => { resending = true; return async ({ update }) => { await update(); resending = false; }; };
</script>
<svelte:head><title>Email login OTP · Godan CRM</title></svelte:head>
<div class="v2-root v2-auth v2-auth-modern v2-auth-code-page"><div class="v2-auth-code-glow"></div><div class="v2-auth-box v2-auth-box-modern v2-auth-code-box"><a href="/" class="v2-auth-brand"><img src={imgLogo} alt=""/><b>Godan CRM</b></a><div class="v2-auth-card v2-auth-card-modern v2-auth-code-card"><div class="v2-auth-code-icon"><MailCheck size={25}/></div><div class="v2-auth-head v2-auth-head-modern"><div class="v2-auth-card-kicker">SECURE EMAIL SIGN-IN</div><h1>Enter your login code</h1><p>If this email belongs to an active account, a six-digit code will arrive at <strong>{data.email}</strong>. Enter it to sign in directly.</p></div>
{#if form?.error}<div class="v2-auth-note v2-auth-note-bad" role="alert">{form.error}</div>{/if}{#if form?.message}<div class="v2-auth-note v2-auth-note-ok" role="status">{form.message}</div>{/if}
<form method="POST" use:enhance={handleVerify} class="v2-auth-form"><div class="v2-auth-field"><label for="code">Email verification code</label><input id="code" name="code" class="v2-input v2-auth-otp-input" bind:value={code} oninput={()=>code=code.replace(/\D/g,'').slice(0,6)} inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="000000" required/><small class="v2-auth-help">Expires in 10 minutes and can only be used once.</small></div><button class="v2-btn v2-btn-primary v2-btn-block v2-auth-submit" disabled={busy||code.length!==6}>{busy?'Signing you in…':'Verify and sign in'}</button></form>
<div class="v2-auth-resend"><span>Didn't receive it?</span><form method="POST" action="?/resend" use:enhance={handleResend}><button disabled={resending}>{resending?'Sending…':'Request new OTP'}</button></form></div><div class="v2-auth-security-note"><ShieldCheck size={16}/><span>Never share your verification code.</span></div></div><a href="/login/forgot-password" class="v2-auth-back"><ArrowLeft size={15}/> Choose another recovery method</a></div></div>
